// Porteiro. A Vercel ja validou o corpo; aqui so se confere QUEM chamou.
//
// O segredo nao e teatro: ele vive no servidor dos dois lados. A pagina do
// painel nunca o ve -- ela fala com a Vercel, e e a Vercel que apresenta isto.
const esperado = String($env.COLLECTOR_CLUB_WEBHOOK_SECRET ?? '');
const veio = String($input.first().json.headers?.authorization ?? '');
if (!esperado || veio !== 'Bearer ' + esperado) {
  throw new Error('Chamada nao autorizada no webhook do Collector Club.');
}

const b = $input.first().json.body ?? {};
const id = String(b.id ?? '').trim();
if (!id) throw new Error('Corpo sem `id`.');

// A Vercel ja normalizou os apelidos antigos; aqui so chegam os tres valores
// finais. Repetir a lista fechada e de proposito: se alguem apontar outro
// chamador para este webhook, a planilha continua protegida.
//
// `decisao` pode ser string vazia de proposito -- e o pedido de LIMPAR a
// celula. Por isso o teste e de presenca, nao de verdade.
if (!('decisao' in b)) throw new Error('Corpo sem `decisao`.');
const decisao = String(b.decisao ?? '');
if (!['APROVADO', 'REJEITADO_USUARIO', ''].includes(decisao)) {
  throw new Error('Decisao invalida: ' + JSON.stringify(b.decisao));
}

// A planilha do Collector Club, a MESMA que o snapshot le a cada 15 minutos.
//
// Cravada aqui em vez de exigir variavel de ambiente: e um id de Drive, nao um
// segredo -- quem controla o acesso e a permissao da conta do Google, nao o
// sigilo do id. Deixar em variavel obrigaria a mexer no host do n8n e
// reiniciar para uma informacao que ja esta publica no workflow do snapshot.
//
// `$env.COLLECTOR_CLUB_SHEET_ID` continua tendo precedencia, para apontar para
// uma copia de teste sem editar o fluxo.
const planilha = String($env.COLLECTOR_CLUB_SHEET_ID || '1Y2lnqYZdzThhyVAoL5O3FCgNPrX1LZcmF4B15M2UMdU');

return [{ json: { id, decisao, em: b.em ?? null, planilha } }];

// Acha a linha do ID e a coluna `internal_status` -- as duas PELO ROTULO.
//
// Coluna identificada por LETRA quebra na primeira vez que alguem insere uma
// coluna no meio, e quebra em silencio: escreve no lugar errado. Identificar
// pelo nome do cabecalho custa dez linhas e sobrevive a planilha viva.
//
// Foi o modo de falha do proprio snapshot do Collector Club em 16/09/2026 --
// o cliente renomeou "Custo final" para "Custo registrado" e o fluxo passou a
// dizer que a aba nao existia. Aqui a licao esta aplicada tres vezes: a ABA e
// descoberta pelo nome, o CABECALHO e procurado, e os dois aceitam variacao de
// acento e de caixa.
//
// A coluna e `internal_status` e nao `Decisao` desde 21/09/2026: e ela que o
// Cowork LE. Gravar na outra seria esquecer a decisao em silencio -- o painel
// marcaria REJEITADO_USUARIO e o radar sugeriria o mesmo relogio amanha.

const norm = (v) => String(v ?? '')
  .normalize('NFD')
  .split('')
  .filter((c) => { const x = c.charCodeAt(0); return x < 0x300 || x > 0x36f; })
  .join('')
  .toUpperCase()
  .replace(/\s+/g, ' ')
  .trim();

const pedido = $('Validar Chamada').first().json;
const linhas = $input.first().json.values || [];
if (!linhas.length) throw new Error('A aba OPORTUNIDADES voltou vazia.');

// O cabecalho nao e necessariamente a linha 1: planilha costuma ter titulo.
let iCab = -1, colId = -1, colDec = -1;
for (let i = 0; i < Math.min(linhas.length, 20); i++) {
  const cels = (linhas[i] || []).map(norm);
  // A aba tem DUAS colunas de identificador: `id`, interno do radar, e
  // `unique_key`, a chave MERCARI_/2NDSTREET_ que o painel conhece e envia.
  // Procurar por `id` daria encontrado:false em toda chamada -- 404 para
  // oportunidade que existe, sem nada apontando a causa.
  const a = cels.indexOf('UNIQUE_KEY') !== -1 ? cels.indexOf('UNIQUE_KEY') : cels.indexOf('ID');
  const b = cels.findIndex((c) => c === 'INTERNAL_STATUS');
  if (a !== -1 && b !== -1) { iCab = i; colId = a; colDec = b; break; }
}
if (iCab === -1) {
  const vistos = linhas.slice(0, 8).map((l) => '[' + (l || []).slice(0, 12).join(' | ') + ']').join('  ');
  throw new Error('Nao achei uma linha de cabecalho com unique_key (ou id) + internal_status. Cabecalhos vistos: ' + vistos);
}

const alvo = norm(pedido.id);
let linha = -1;
for (let i = iCab + 1; i < linhas.length; i++) {
  if (norm((linhas[i] || [])[colId]) === alvo) { linha = i + 1; break; }
}

if (linha === -1) {
  return [{ json: { encontrado: false, id: pedido.id } }];
}

// Indice de coluna -> letra (A, B, ... Z, AA...). Vale ate colunas alem de Z,
// que uma aba de oportunidades alcanca sem esforco.
let n = colDec, letra = '';
do { letra = String.fromCharCode(65 + (n % 26)) + letra; n = Math.floor(n / 26) - 1; } while (n >= 0);

return [{ json: {
  encontrado: true,
  id: pedido.id,
  decisao: pedido.decisao,
  em: pedido.em,
  planilha: pedido.planilha,
  linha,
  intervalo: $('Escolher Aba').first().json.abaA1 + '!' + letra + linha,
} }];

// A aba pelo NOME, comparando sem acento e sem caixa.
//
// O spec escreveu "Oportunidades" e depois "OPORTUNIDADES". Em A1 notation o
// nome da aba e sensivel a caixa, entao uma letra maiuscula a mais derrubaria
// a gravacao com um erro que nao diz isso. Descobrir e casar custa um nó.
const norm = (v) => String(v ?? "")
  .normalize("NFD")
  .split("")
  .filter((c) => { const x = c.charCodeAt(0); return x < 0x300 || x > 0x36f; })
  .join("")
  .toUpperCase()
  .trim();

const abas = ($input.first().json.sheets || []).map((s) => s.properties.title);
const alvo = abas.find((t) => norm(t) === "OPORTUNIDADES");
if (!alvo) {
  throw new Error("Nao achei a aba OPORTUNIDADES. Abas da planilha: " + abas.join(" | "));
}
// `abaA1` e o mesmo nome pronto para A1 notation. Nome de aba com espaco
// precisa de aspas simples na faixa ("'Vendas de Terceiros'!A1"), e aspa
// interna se escapa dobrando.
//
// O caso que isto protege nao e o rename: nome diferente nao casa aqui e
// para com erro claro. E o espaco INVISIVEL -- uma aba chamada
// "OPORTUNIDADES " passa no casamento por causa do trim, e a faixa sem
// aspas viraria "OPORTUNIDADES !J2", que a API recusa sem dizer por que.
const abaA1 = "'" + alvo.replace(/'/g, "''") + "'";
return [{ json: { aba: alvo, abaA1 } }];
